svg.script:
/**/
function a12p7bSetState(newState) {
  var svg = document.getElementById('a12p7b-svg');
  if (!svg) return;

  // Atualiza atributo de estado na raiz
  svg.setAttribute('data-state', newState);

  // Atualiza aria-pressed nos botões
  var states = ['integra', 'canal', 'segura', 'parede'];
  states.forEach(function(st) {
    var btn = document.getElementById('a12p7b-btn-' + st);
    if (btn) {
      btn.setAttribute('aria-pressed', st === newState ? 'true' : 'false');
    }
  });
}
/**/
